extends "res://tests/test_source_natural_contact_main.gd"
const ReviewFuel=preload("res://scripts/source_fuel_contact.gd")
var review_timings:Array=[]
var review_orientation:={"cases":0,"max_axis_distance":0.0,"max_axis_direction_distance":0.0,"min_determinant":1.0,"immutable":true}
func measure_case(label:String)->void:
 var before:=live_natural_state();var samples:Array=[];var calls:Array=[]
 for index in range(5):
  var started:=Time.get_ticks_usec();var value:=NaturalProbe.sample(game.world,game.ship,game.surface,game.nav.elapsed_days);var elapsed:=Time.get_ticks_usec()-started
  check(value.get("ok",false),"Review direct query succeeds "+label);samples.append(elapsed);calls.append(value.get("terrain_query_calls",-1))
 check(live_natural_state()==before,"Review timed direct query is immutable "+label)
 var main_samples:Array=[]
 for index in range(3):
  var started:=Time.get_ticks_usec();game._flight_diagnostic_sample();main_samples.append(Time.get_ticks_usec()-started)
 check(live_natural_state()==before,"Review timed Main sample is immutable "+label)
 review_timings.append({"case":label,"direct_probe_microseconds":samples,"direct_query_calls":calls,"actual_Main_flight_sample_microseconds":main_samples,"first_sample_policy":"first call for this observer; shared resource caches may already be warm","unchanged_model_state":live_natural_state()==before})
func orientation_cases()->void:
 var original_attitude:Quaternion=game.ship.attitude
 var before:=live_natural_state()
 for body_id:String in ["earth","mercury","star"]:
  var body:Dictionary=game.world.by_id[body_id]
  for days:float in [0.0,0.25,17.25]:
   var rotation:=ReviewFuel._basis_readonly(game.world,body,days)
   for euler:Vector3 in [Vector3.ZERO,Vector3(0.23,-0.91,0.61),Vector3(-1.3,2.1,0.7)]:
    game.ship.attitude=Quaternion.from_euler(euler)
    var matrix:=NaturalProbe._orientation(game.world,game.ship,null,body,days)
    var actual:=Basis(Vector3(matrix[0],matrix[1],matrix[2])/2147483648.0,Vector3(matrix[3],matrix[4],matrix[5])/2147483648.0,Vector3(matrix[6],matrix[7],matrix[8])/2147483648.0)
    var local:Basis=rotation.basis.inverse()*Basis(game.ship.attitude)
    var distance:=maxf(actual.x.distance_to(-local.x),maxf(actual.y.distance_to(local.y),actual.z.distance_to(-local.z)))
    var direction_distance:=maxf(actual.x.normalized().distance_to(-local.x.normalized()),maxf(actual.y.normalized().distance_to(local.y.normalized()),actual.z.normalized().distance_to(-local.z.normalized())))
    review_orientation.cases+=1;review_orientation.max_axis_distance=maxf(review_orientation.max_axis_distance,distance);review_orientation.max_axis_direction_distance=maxf(review_orientation.max_axis_direction_distance,direction_distance);review_orientation.min_determinant=minf(review_orientation.min_determinant,actual.determinant())
    check(direction_distance<0.00001 and actual.determinant()>0.9,"Review source Q31 matrix follows the same inverse rotating body frame and proper local yaw(pi)")
 game.ship.attitude=original_attitude
 review_orientation.immutable=live_natural_state()==before
 check(review_orientation.immutable,"Review rotation advance remains isolated from live spin and ephemeris")
func run()->void:
 if not "--rebuild-capture" in OS.get_cmdline_user_args():quit(1);return
 root.size=Vector2i(1440,720);game=load("res://scenes/main.tscn").instantiate();game.settings=MemorySettings.new();root.add_child(game);game.set_process(false);game.set_physics_process(false);await frame();initialize_probe_diagnostics()
 for body_id:String in ["earth","mercury"]:
  fresh();game.settings.orbital_gravity=false;stage_natural(body_id,5000,0)
  measure_case("actual_"+body_id+"_orbital_5000m")
  if body_id=="earth":orientation_cases()
  await game._enter_surface();check(game.surface.active,"Review actual source surface entry")
  if game.surface.active:measure_case("actual_"+body_id+"_active_source_surface")
 fresh();game.settings.orbital_gravity=false;stage_natural("mercury",5000,0)
 var before:=live_natural_state();var reports:Array=[]
 game.report_draft="Private desktop duration review";game.report_include_save=false
 for index in range(3):
  var started:=Time.get_ticks_usec();await game._create_bug_report(false);reports.append({"microseconds_including_awaited_process_frame":Time.get_ticks_usec()-started,"ok":game.current_report.get("ok",false),"report_bytes":game.current_report.get("report_bytes",0)})
  check(game.current_report.get("ok",false),"Review actual report collector succeeds")
 check(live_natural_state()==before,"Review actual report collection preserves model/HP/RNG/fuel/time state")
 var report:={"checks":checks,"failures":failures,"timings":review_timings,"orientation":review_orientation,"report_collection":reports,"report_model_state_unchanged":live_natural_state()==before,"duration_scope":"one managed desktop headless Godot process; limited repeated observations only; not S23/Android timing, frame-rate, complete workload or thermal proof"}
 var file:=FileAccess.open("/tmp/starfrontier-natural-integration-review-execution.json",FileAccess.WRITE);file.store_string(JSON.stringify(report,"  "));file.close()
 print("INTEGRATION REVIEW: ",JSON.stringify(report));game.queue_free();await frame();quit(1 if failures else 0)
